<script lang="ts">
 import { onMount } from 'svelte';
 import type { State,Config,Action } from './types';
 let sim=$state<State|null>(null), config=$state<Config|null>(null);
 let connected=$state(false),error=$state(''),busy=$state(0),tool=$state('paint'),showImport=$state(false),showGuide=$state(false),focus=$state(false);
 let importText=$state(''),sourceURL=$state(''),ruleInput=$state('B3/S23'),seed=$state(42),density=$state(.28),jump=$state(1024);
 let canvas:HTMLCanvasElement,mini:HTMLCanvasElement,field:HTMLDivElement;
 let width=$state(800),height=$state(600),hover=$state<{x:number;y:number}|null>(null);
 let pointer:{id:number;x:number;y:number;wx:number;wy:number;pan:boolean;erase:boolean;camera:{x:number;y:number}}|null=null;
 let queue=Promise.resolve();
 const names:Record<string,string>={gosper:'Glider gun',glider:'Glider',acorn:'Acorn',rpentomino:'R-pentomino',pulsar:'Pulsar',lwss:'Lightweight ship',diehard:'Diehard',replicator:'Replicator',blinker:'Blinker',toad:'Toad',beacon:'Beacon',block:'Block',life:'Conway’s Life','brians-brain':'Brian’s Brain','langtons-ant':'Langton’s Ant','larger-than-life':'Larger than Life',faders:'Faders','forest-fire':'Forest Fire',wildfire:'Wildfire',belousov:'Cyclic reaction'};
 const palettes:Record<string,string[]>={mint:['#bbfbce','#2ea48d','#b4f09a'],neon:['#5fe7ff','#be78ff','#ff7ece'],amber:['#ffd575','#e6813a','#ffd575'],sunset:['#ffad7c','#e05c9a','#fbcf7e'],mono:['#f0f4f2','#7d9293','#f0f4f2']};
 function receive(next:State){if(!sim||next.revision>=sim.revision){const changed=sim?.rule!==next.rule;sim=next;if(changed)ruleInput=next.rule;}}
 function act(action:Action):Promise<void>{busy++;const request=async()=>{try{const res=await fetch('/api/action',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(action)});if(!res.ok)throw new Error(await res.text());receive(await res.json());error='';}catch(e){error=e instanceof Error?e.message:String(e);}finally{busy--;}};queue=queue.then(request,request);return queue;}
 function color(age:number,status:number){const colors=palettes[sim?.theme??'mint'];if(status>1)return status===2?'#d6a76b':colors[1];return age<4?colors[0]:age<24?colors[2]:colors[1];}
 function worldPoint(x:number,y:number){const c=sim!.camera;return {x:Math.floor(c.x+(x-width/2)*c.zoom/6),y:Math.floor(c.y+(y-height/2)*c.zoom/6)};}
 function fit(){act({type:'fit',x:Math.floor(width/6),y:Math.floor(height/6)});}
 function draw(){if(!canvas||!sim)return;const ratio=window.devicePixelRatio||1;const pw=Math.round(width*ratio),ph=Math.round(height*ratio);if(canvas.width!==pw||canvas.height!==ph){canvas.width=pw;canvas.height=ph;}const ctx=canvas.getContext('2d')!;ctx.setTransform(ratio,0,0,ratio,0,0);ctx.fillStyle='#0b1115';ctx.fillRect(0,0,width,height);const unit=6/sim.camera.zoom,c=sim.camera,ox=width/2-c.x*unit,oy=height/2-c.y*unit;
  if(sim.grid){const step=unit*(unit<3?64:unit<8?8:1);if(step>=4){ctx.strokeStyle='#19262a';ctx.lineWidth=.5;ctx.beginPath();for(let x=((ox%step)+step)%step;x<width;x+=step){ctx.moveTo(x,0);ctx.lineTo(x,height);}for(let y=((oy%step)+step)%step;y<height;y+=step){ctx.moveTo(0,y);ctx.lineTo(width,y);}ctx.stroke();}}
  const cell=(x:number,y:number,fill:string,alpha=1)=>{const px=ox+x*unit,py=oy+y*unit;if(px>width||py>height||px+unit<0||py+unit<0)return;ctx.globalAlpha=alpha;ctx.fillStyle=fill;const gap=unit>9?1:0;ctx.fillRect(Math.floor(px),Math.floor(py),Math.max(1,Math.ceil(unit)-gap),Math.max(1,Math.ceil(unit)-gap));};
  for(const [x,y,t] of sim.trails)cell(x,y,palettes[sim.theme][1],t/24);
  for(const [x,y,age,status] of sim.cells)cell(x,y,color(age,status));
  if(sim.mode==='langtons-ant')cell(sim.ant.x,sim.ant.y,'#ff9a76');ctx.globalAlpha=1;
  if(hover&&tool!=='pan'){const x=ox+hover.x*unit,y=oy+hover.y*unit;ctx.strokeStyle=tool==='erase'?'#ee9d85':'#c6f6ab';ctx.lineWidth=1;ctx.strokeRect(Math.floor(x)-1,Math.floor(y)-1,Math.max(3,unit)+2,Math.max(3,unit)+2);}
  drawMini();
 }
 function drawMini(){if(!mini||!sim)return;const ctx=mini.getContext('2d')!;ctx.clearRect(0,0,160,90);ctx.fillStyle='#101a1e';ctx.fillRect(0,0,160,90);if(!sim.cells.length)return;let minX=Infinity,minY=Infinity,maxX=-Infinity,maxY=-Infinity;for(const[x,y]of sim.cells){minX=Math.min(minX,x);minY=Math.min(minY,y);maxX=Math.max(maxX,x);maxY=Math.max(maxY,y);}const k=Math.min(140/Math.max(1,maxX-minX+1),70/Math.max(1,maxY-minY+1));const cx=(minX+maxX)/2,cy=(minY+maxY)/2;ctx.fillStyle=palettes[sim.theme][2];for(const[x,y]of sim.cells)ctx.fillRect(80+(x-cx)*k,45+(y-cy)*k,Math.max(1,k),Math.max(1,k));ctx.strokeStyle='#829e9b';ctx.strokeRect(80+(sim.camera.x-cx-width*sim.camera.zoom/12)*k,45+(sim.camera.y-cy-height*sim.camera.zoom/12)*k,width*sim.camera.zoom/6*k,height*sim.camera.zoom/6*k);}
 function miniJump(e:MouseEvent){if(!sim?.cells.length)return;const bounds=mini.getBoundingClientRect();let minX=Infinity,minY=Infinity,maxX=-Infinity,maxY=-Infinity;for(const[x,y]of sim.cells){minX=Math.min(minX,x);maxX=Math.max(maxX,x);minY=Math.min(minY,y);maxY=Math.max(maxY,y);}const k=Math.min(140/Math.max(1,maxX-minX+1),70/Math.max(1,maxY-minY+1));act({type:'jump',x:Math.round((minX+maxX)/2+((e.clientX-bounds.left)*160/bounds.width-80)/k),y:Math.round((minY+maxY)/2+((e.clientY-bounds.top)*90/bounds.height-45)/k)});}
 function down(e:PointerEvent){if(!sim)return;canvas.setPointerCapture(e.pointerId);const rect=canvas.getBoundingClientRect(),x=e.clientX-rect.left,y=e.clientY-rect.top,p=worldPoint(x,y);pointer={id:e.pointerId,x,y,wx:p.x,wy:p.y,pan:tool==='pan'||e.button===1||e.shiftKey,erase:tool==='erase'||e.button===2,camera:{x:sim.camera.x,y:sim.camera.y}};if(!pointer.pan)act({type:'paint',x:p.x,y:p.y,x2:p.x,y2:p.y,erase:pointer.erase});}
 function move(e:PointerEvent){if(!sim)return;const rect=canvas.getBoundingClientRect(),x=e.clientX-rect.left,y=e.clientY-rect.top,p=worldPoint(x,y);hover=p;if(!pointer)return;if(pointer.pan){act({type:'jump',x:Math.round(pointer.camera.x-(x-pointer.x)*sim.camera.zoom/6),y:Math.round(pointer.camera.y-(y-pointer.y)*sim.camera.zoom/6)});}else if(p.x!==pointer.wx||p.y!==pointer.wy){act({type:'paint',x:pointer.wx,y:pointer.wy,x2:p.x,y2:p.y,erase:pointer.erase});pointer.wx=p.x;pointer.wy=p.y;}}
 function up(){pointer=null;}
 function wheel(e:WheelEvent){e.preventDefault();act({type:'zoom',number:e.deltaY>0?1.2:1/1.2});}
 async function generate(){await act({type:'seed',number:seed});await act({type:'density',number:density});await act({type:'random',x:160,y:96});}
 async function importFile(e:Event){const file=(e.target as HTMLInputElement).files?.[0];if(!file)return;if(file.size>4*1024*1024){error='Pattern files must be smaller than 4 MiB.';return;}importText=await file.text();}
 async function importPattern(){if(sourceURL.trim())await act({type:'source',value:sourceURL.trim()});else await act({type:'load',text:importText});if(!error){showImport=false;fit();}}
 function savePNG(){canvas.toBlob(blob=>{if(!blob)return;const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download='hilife.png';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000);});}
 function keydown(e:KeyboardEvent){if(e.key==='Escape'){showGuide=false;showImport=false;focus=false;return;}if((e.target as HTMLElement)?.closest('input,textarea,select,[contenteditable]'))return;if(showGuide||showImport)return;let a:Action|undefined;switch(e.key){case ' ':a={type:'toggle'};break;case 't':case 'n':a={type:'step'};break;case 'u':a={type:'undo'};break;case 'r':a={type:'reset'};break;case 'R':generate();break;case 'c':a={type:'clear'};break;case '+':case '=':a={type:'zoom',number:.8};break;case '-':a={type:'zoom',number:1.25};break;case 'g':a={type:'grid'};break;case 'l':a={type:'trails'};break;case '0':fit();break;case 'h':a={type:'home'};break;case 'f':focus=!focus;break;case '?':showGuide=true;break;case 'w':case 'ArrowUp':a={type:'pan',y:-8};break;case 's':case 'ArrowDown':a={type:'pan',y:8};break;case 'a':case 'ArrowLeft':a={type:'pan',x:-8};break;case 'd':case 'ArrowRight':a={type:'pan',x:8};break;}if(a){e.preventDefault();act(a);}}
 $effect(()=>{sim;hover;width;height;tool;draw();});
 onMount(()=>{let alive=true;fetch('/api/config').then(r=>r.json()).then(c=>config=c).catch(e=>error=String(e));fetch('/api/state').then(r=>r.json()).then(s=>{if(alive)receive(s);}).catch(e=>error=String(e));const events=new EventSource('/api/events');events.onopen=()=>connected=true;events.onerror=()=>connected=false;events.onmessage=e=>receive(JSON.parse(e.data));const observer=new ResizeObserver(entries=>{for(const e of entries){width=e.contentRect.width;height=e.contentRect.height;}});observer.observe(field);window.addEventListener('keydown',keydown);return()=>{alive=false;events.close();observer.disconnect();window.removeEventListener('keydown',keydown);};});
</script>

<div class:focus class="app-shell">
 <header class="topbar">
  <a class="wordmark" href="/" aria-label="hiLife home"><span class="brand-grid" aria-hidden="true"><i></i><i></i><i></i><i></i><i></i></span>hi<span>Life</span><sup>01</sup></a>
  <div class="nav-label">A CELLULAR PLAYGROUND <span>/</span> ENDLESS POSSIBILITIES</div>
  <div class="top-actions"><span class:online={connected} class="connection"><i></i>{connected?'LIVE ENGINE':'CONNECTING'}</span><button class="quiet" onclick={()=>showGuide=true}>Field guide <span>↗</span></button><a class="quiet terminal-link" href="https://github.com/charmbracelet/bubbletea" target="_blank" rel="noreferrer">BUILT WITH CHARM</a></div>
 </header>

 <div class="workspace">
  <aside class="sidebar">
   <div class="intro"><span class="eyebrow">SMALL RULES. BIG WORLDS.</span><h1>Watch life<br/>find a way<span>.</span></h1><p>Plant a pattern. Change the rules.<br/>See what emerges.</p></div>
   <section class="seed-section"><div class="section-heading"><span>01 / PLANT A SEED</span><button class="text-button" onclick={()=>showImport=true}>Import ↗</button></div>
    <div class="preset-grid">{#each (config?.presets??[]).slice(0,6) as p,i}<button class:active={sim?.name===p.name} class="preset" title={p.description} onclick={async()=>{await act({type:'pattern',value:p.name});fit();}}><span class="seed-icon" aria-hidden="true">{#each Array(25) as _,j}<i class:lit={((j*(i+3)+i*7)%13)<5}></i>{/each}</span><span>{names[p.name]}</span></button>{/each}</div>
    <select class="more-patterns" aria-label="More patterns" value="" onchange={async e=>{await act({type:'pattern',value:e.currentTarget.value});fit();}}><option value="" disabled>More patterns …</option>{#each (config?.presets??[]).slice(6) as p}<option value={p.name}>{names[p.name]??p.name} — {p.description}</option>{/each}</select>
   </section>
   <section><div class="section-heading"><span>02 / SET THE RULES</span><span class="tiny-label">EXPERIMENT</span></div><label class="field-label" for="automaton">Automaton</label><select id="automaton" value={sim?.mode??'life'} onchange={e=>act({type:'mode',value:e.currentTarget.value})}>{#each config?.modes??['life'] as m}<option value={m}>{names[m]??m}</option>{/each}</select><label class="field-label rule-label" for="rule">Birth / survival <span>↵ to apply</span></label><input id="rule" class="rule-input" bind:value={ruleInput} onkeydown={e=>{if(e.key==='Enter')act({type:'rule',value:ruleInput});}} onblur={()=>{if(ruleInput!==sim?.rule)act({type:'rule',value:ruleInput});}} disabled={sim?.mode!=='life'}/>
    <div class="toggle-row"><label for="trails">Fading trails</label><button id="trails" aria-label="Fading trails" role="switch" aria-checked={sim?.showTrails??false} class:on={sim?.showTrails} class="switch" onclick={()=>act({type:'trails'})}><span></span></button></div><div class="toggle-row"><label for="grid">Grid overlay</label><button id="grid" aria-label="Grid overlay" role="switch" aria-checked={sim?.grid??false} class:on={sim?.grid} class="switch" onclick={()=>act({type:'grid'})}><span></span></button></div><div class="toggle-row"><label for="wrap">Wrap edges <small>{sim?.width}×{sim?.height}</small></label><button id="wrap" aria-label="Wrap edges" role="switch" aria-checked={sim?.wrap??false} class:on={sim?.wrap} class="switch" onclick={()=>act({type:'wrap'})}><span></span></button></div>
   </section>
   <section><div class="section-heading"><span>03 / MAKE IT YOURS</span></div><div class="swatches">{#each config?.themes??['mint'] as theme}<button aria-label={`${theme} theme`} title={theme} class:selected={sim?.theme===theme} style={`--swatch:${palettes[theme][2]}`} onclick={()=>act({type:'theme',value:theme})}></button>{/each}<span>{sim?.theme??'mint'}</span></div><details><summary>Random world <span>＋</span></summary><div class="random-fields"><label>Seed<input type="number" min="0" bind:value={seed}/></label><label>Density<input type="number" min="0" max="1" step=".01" bind:value={density}/></label></div><button class="outline full" onclick={generate}>Generate world ↗</button></details></section>
   <div class="sidebar-foot"><span class="little-cross">✳</span><p>Complexity starts<br/>with something simple.</p></div>
  </aside>

  <main>
   <div class="world-heading"><div><div class="eyebrow">THE OBSERVATION DECK</div><h2>{names[sim?.name??'gosper']??sim?.name??'Glider gun'}<span class="rule-badge">{sim?.rule??'B3/S23'}</span></h2></div><div class="document-actions"><button class="quiet" onclick={()=>showImport=true}>↥ Import</button><div class="export-menu"><button class="outline">↧ Export</button><div><a href="/api/export?format=rle" download>Pattern · RLE</a><a href="/api/export?format=json" download>World · JSON</a><button onclick={savePNG}>Snapshot · PNG</button></div></div></div></div>
   <div class="metrics"><div><span>GENERATION</span><strong>{(sim?.generation??0).toLocaleString()}</strong></div><div><span>LIVING CELLS</span><strong>{(sim?.population??0).toLocaleString()}<i class="live-dot"></i></strong></div><div><span>LAST ADVANCE</span><strong class="changes"><b>+{sim?.births??0}</b><em>−{sim?.deaths??0}</em></strong></div><div><span>ENGINE TIME</span><strong>{(sim?.stepMs??0).toFixed(2)}<small>ms</small></strong></div></div>
   <div class="field" class:panning={tool==='pan'} bind:this={field}>
    <canvas bind:this={canvas} aria-label="Cellular automata board. Drag to paint, right-drag to erase, shift-drag to pan." onpointerdown={down} onpointermove={move} onpointerup={up} onpointercancel={up} onpointerleave={()=>{hover=null;if(!pointer)up();}} onwheel={wheel} oncontextmenu={e=>e.preventDefault()}></canvas>
    <div class="field-top"><span class="board-status"><i class:running={sim?.running}></i>{sim?.running?'EVOLVING':'PAUSED'}<span> / {names[sim?.mode??'life']}</span></span><button class="icon-button" aria-label={focus?'Exit focus mode':'Enter focus mode'} title="Focus · F" onclick={()=>focus=!focus}>{focus?'↙':'↗'}</button></div>
    <div class="toolbox" aria-label="Drawing tools">{#each [['paint','✎','Paint'],['erase','⌫','Erase'],['pan','✥','Pan']] as [id,icon,label]}<button class:chosen={tool===id} aria-pressed={tool===id} title={label} onclick={()=>tool=id}><span>{icon}</span>{label}</button>{/each}</div>
    <div class="minimap"><span>WORLD OVERVIEW <i>↗</i></span><button aria-label="Jump to a position in the minimap" onclick={miniJump}><canvas bind:this={mini} width="160" height="90" aria-label="World minimap"></canvas></button></div>
    <div class="field-bottom"><span>{hover?`${hover.x}, ${hover.y}`:`${Math.round(sim?.camera.x??0)}, ${Math.round(sim?.camera.y??0)}`}<i>WORLD COORDINATES</i></span><div class="zoom-controls"><button aria-label="Zoom out" onclick={()=>act({type:'zoom',number:1.25})}>−</button><span>{Math.round(100/(sim?.camera.zoom??1))}%</span><button aria-label="Zoom in" onclick={()=>act({type:'zoom',number:.8})}>+</button><button class="fit" onclick={fit}>Fit ↗</button></div></div>
    {#if !sim}<div class="loading">Connecting to your universe…</div>{/if}
   </div>
   <div class="transport"><div class="play-controls"><button class="play" onclick={()=>act({type:'toggle'})} aria-label={sim?.running?'Pause simulation':'Run simulation'}><span>{sim?.running?'Ⅱ':'▶'}</span>{sim?.running?'Pause':'Run'}<kbd>SPACE</kbd></button><button class="outline step" onclick={()=>act({type:'step'})}>▹ Step</button><button class="icon-button" title="Undo · U" aria-label="Undo" disabled={!sim?.undo} onclick={()=>act({type:'undo'})}>↶</button><button class="icon-button" title="Reset · R" aria-label="Reset pattern" onclick={()=>act({type:'reset'})}>↺</button><button class="icon-button" title="Clear board · C" aria-label="Clear board" onclick={()=>act({type:'clear'})}>⌫</button></div><div class="speed"><label for="speed">SPEED <strong>{sim?.tps??20}<small>gen/s</small></strong></label><input id="speed" type="range" min="1" max="120" value={Math.min(120,sim?.tps??20)} oninput={e=>act({type:'speed',number:+e.currentTarget.value})}/></div><div class="jump-controls"><select aria-label="Fast-forward generations" bind:value={jump}><option value={64}>64 generations</option><option value={1024}>1,024 generations</option><option value={65536}>65,536 generations</option><option value={1048576}>1,048,576 generations</option></select><button class="outline" disabled={busy>0} onclick={()=>act({type:'advance',number:+jump})}>Jump ↗</button></div></div>
   <footer class="canvas-footer"><span>Drag to draw <b>·</b> Right-drag to erase <b>·</b> Shift-drag to explore</span><span>{sim?.chunks??0} chunks <b>·</b> {sim?.cache??0} cached futures <b>·</b><button class="text-button" onclick={()=>showGuide=true}>Keyboard shortcuts ↗</button></span></footer>
  </main>
 </div>
 {#if error}<div class="toast" role="alert"><span>{error}</span><button aria-label="Dismiss error" onclick={()=>error=''}>×</button></div>{/if}
 {#if showImport||showGuide}<div class="modal-backdrop" role="presentation" onclick={e=>{if(e.target===e.currentTarget){showImport=false;showGuide=false;}}}><div class="modal" role="dialog" aria-modal="true" aria-label={showImport?'Import a pattern':'Field guide'} tabindex="-1"><button class="modal-close icon-button" aria-label="Close dialog" onclick={()=>{showImport=false;showGuide=false;}}>×</button>{#if showImport}<span class="eyebrow">BRING YOUR OWN UNIVERSE</span><h2>Import a pattern<span>.</span></h2><p>Load RLE, plaintext or JSON. LifeWiki page URLs work too.</p><input type="file" accept=".rle,.cells,.json,.txt" onchange={importFile}/><textarea aria-label="Pattern text" bind:value={importText} placeholder="Paste pattern text here…" rows="9"></textarea><label class="field-label" for="url">Or import from a URL</label><input id="url" type="url" bind:value={sourceURL} placeholder="https://conwaylife.com/wiki/…"/><button class="play full" disabled={busy>0||(!importText&&!sourceURL)} onclick={importPattern}>{busy?'Loading…':'Plant pattern ↗'}</button>{:else}<span class="eyebrow">THE FIELD GUIDE</span><h2>Small rules.<br/>Unexpected worlds<span>.</span></h2><p>Live cells survive with two or three neighbours. An empty cell is born with three. Everything else is up to the pattern.</p><div class="shortcuts">{#each [['Space','Run / pause'],['T / N','Step one generation'],['U','Undo'],['R / Shift R','Reset / seeded random world'],['W A S D / arrows','Pan the camera'],['+ / −','Zoom'],['0','Fit pattern'],['H','Go to origin'],['G / L','Grid / trails'],['F','Focus mode'],['C','Clear board']] as [k,label]}<span><kbd>{k}</kbd>{label}</span>{/each}</div><p class="guide-note">Fast-forward uses HashLife in Life mode without trails or wrapping. Other modes support jumps up to 4,096 generations. JSON preserves absolute positions; RLE exports normalize the origin.</p>{/if}</div></div>{/if}
</div>
